parameters.jsCode:
const rows = $input.all();

const lines = rows.map(r => {
  const m = r.json.message;
  if (!m) return null;

  if (typeof m === 'string') {
    return `Cliente: ${m}`;
  }

  if (typeof m === 'object') {
    const type = m.type || m.role;
    const content = (m.data && m.data.content) || m.content || '';
    if (!content) return null;
    if (type === 'human') return `Cliente: ${content}`;
    if (type === 'ai') return `Vitória: ${content}`;
  }

  return null;
}).filter(Boolean);

return [{ json: { formattedHistory: lines.join('\n') } }];

