parameters.jsCode:
const raw = $input.first().json.output;
let jsonStr = null;
try {
  const s = raw.indexOf('{');
  const e = raw.lastIndexOf('}');
  if (s === -1 || e === -1) throw new Error('JSON não encontrado');
  jsonStr = raw.substring(s, e + 1);
  const p = JSON.parse(jsonStr);
  return [{
    json: {
      classification: p.classification,
      reason: p.reason,
      motivo_desqualificacao: p.motivo_desqualificacao || 'fora_icp',
      name: p.lead_data.name,
      phone: p.lead_data.phone,
      tratamento_interesse: p.lead_data.tratamento_interesse,
      possui_medico: p.lead_data.possui_medico,
      urgencia: p.lead_data.urgencia,
      turno_preferido: p.lead_data.turno_preferido,
      handoff_motivo: p.lead_data.handoff_motivo,
      data_nascimento: p.lead_data.data_nascimento || 'Não informado',
      possui_exames: p.lead_data.possui_exames || 'Não informado'
    }
  }];
} catch (err) {
  return [{ json: { error: err.message, rawOutput: raw, extracted: jsonStr } }];
}

